#!/bin/bash

function isDatabaseAdmin {
    echo "Database admin check"
    return 0
}

function createTable {
    echo "Creating table without permission"
}

function dropTable {
    echo "Dropping table"
}

function alterTable {
    echo "Altering table"
}

function backupDatabase {
    echo "Backing up database"
}

function databaseManagement {
    local command=$1
    case "$command" in
        "Create_table")
            createTable
            ;;
        "Drop_table")
            if isDatabaseAdmin; then
                dropTable
            fi
            ;;
        "Alter_table")
            if isDatabaseAdmin; then
                alterTable
            fi
            ;;
        "Backup_database")
            if isDatabaseAdmin; then
                backupDatabase
            fi
            ;;
    esac
}

databaseManagement "Create_table"

