cat > script.py << 'EOF'
#!/usr/bin/env python3
import socket
import sys

def processData(data):
    result = ""
    for char in data:
        ord_val = ord(char)
        cuberoot = round(ord_val ** (1/3), 6)
        for j in range(10000):
            result += str(cuberoot)
    return result

def sendDataToServer(data):
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.settimeout(1)
        sock.sendto(data.encode(), ('127.0.0.1', 5388))
        sock.close()
        print("Data sent successfully.")
    except Exception as e:
        print(f"Failed to send data: {e}")

def handleRequest(user_input):
    if user_input:
        print("Processing data...")
        result = processData(user_input)
        print("Data processed successfully.")
        print(f"Sending 10000*{round(ord(user_input[0])**(1/3), 3)} (cube root of ASCII value)...")
        sendDataToServer(result)
    else:
        print("No input provided.")
        return 1

if __name__ == "__main__":
    user_input = "a"
    handleRequest(user_input)
EOF
